<template>
  <view class="page-shell">
    <view class="top-nav" :style="{ height: `${navHeight}px`, paddingTop: `${navTop}px` }"><sravx-page-back mode="nav" /><text class="nav-title">购物袋</text></view>
    <view class="page" :style="{ paddingTop: `${navHeight}px` }">
      <view v-if="items.length" class="bag-content"><view class="bag-heading"><text>购物袋</text><text class="ui-small">{{totalCount}} 件商品</text></view><view class="bag-list"><view v-for="(item,index) in items" :key="`${item.id}-${index}`" class="bag-card"><image :src="item.cover_image" mode="aspectFill"/><view class="bag-info"><text class="bag-name">{{item.name}}</text><text v-if="item.selectedModel" class="spec">型号：{{item.selectedModel}}</text><text v-if="item.protectSelected" class="protect">已选 SRAVX Protect</text><text v-if="!item.selectedModel&&item.spec" class="spec">{{item.spec}}</text><text class="price">¥{{item.priceText}}</text><view class="actions"><view class="stepper"><view @tap="decrease(index)">−</view><text>{{item.quantity}}</text><view @tap="increase(index)">＋</view></view><text class="remove" @tap="remove(index)">移除</text></view></view><view class="checkout" @tap="checkout(index)">结账</view></view></view><view class="total"><text>共计 {{totalCount}} 件</text><text>¥{{totalPrice}}</text></view></view>
      <view v-else class="empty"><view class="bag-icon"><view/><text/></view><text class="empty-title">购物袋还是空的</text><text class="ui-small">从产品页选择喜欢的专业工具</text><view class="browse" @tap="browse">浏览产品</view></view>
    </view>
    <SravxTabBar active-path="/pages/cart/index" />
  </view>
</template>
<script>
import SravxPageBack from '../../components/sravx-page-back/sravx-page-back.vue'

import cart from '../../common/cart.js'
import SravxTabBar from '../../components/SravxTabBar.vue'
function price(value){return(Number(value)||0).toFixed(2)}
export default { components:{ SravxPageBack, SravxTabBar}, data(){return{items:[],totalCount:0,totalPrice:'0.00',navTop:8,navHeight:56}}, onLoad(){this.initNav()}, onShow(){this.load()}, methods:{ initNav(){try{const menu=uni.getMenuButtonBoundingClientRect();this.navTop=menu.top;this.navHeight=menu.bottom+8}catch(error){}}, load(){this.items=cart.list().map(item=>({...item,priceText:price(item.price)}));this.totalCount=this.items.reduce((sum,item)=>sum+item.quantity,0);this.totalPrice=price(this.items.reduce((sum,item)=>sum+item.price*item.quantity,0))}, decrease(index){const item=this.items[index];if(!item)return;if(item.quantity<=1){this.remove(index);return}cart.update(index,item.quantity-1);this.load()}, increase(index){const item=this.items[index];if(!item)return;cart.update(index,item.quantity+1);this.load()}, remove(index){uni.showModal({title:'移出购物袋',content:'确定移除这件商品？',confirmColor:'#69727E',success:result=>{if(result.confirm){cart.remove(index);this.load()}}})}, checkout(index){const item=this.items[index];if(!item)return;const productData=encodeURIComponent(JSON.stringify({id:item.id,skuId:item.skuId,name:item.name,price:item.price,cover_image:item.cover_image,selectedModel:item.selectedModel,selectedSpecName:item.selectedSpecName,protectSelected:item.protectSelected,protectOfferId:item.protectOfferId,protectDisplayOnly:item.protectDisplayOnly,spec:item.spec,quantity:item.quantity,allow_coupon:item.allow_coupon}));uni.navigateTo({url:`/pages/confirm-order/index?productData=${productData}`})}, browse(){uni.reLaunch({url:'/pages/index/index'})} } }
</script>
<style>
.page-shell{height:100vh;background:#F4F6F8}.top-nav{position:fixed;z-index:10;top:0;right:0;left:0;box-sizing:border-box;background:rgba(255,255,255,.96);border-bottom:1px solid rgba(60,60,67,.08)}.nav-title{position:absolute;bottom:13px;left:0;right:0;text-align:center;color:#0B0D10;font-size:16px;font-weight:600}.page{min-height:100vh;padding-right:28rpx;padding-bottom:calc(env(safe-area-inset-bottom) + 160rpx);padding-left:28rpx;box-sizing:border-box;background:#F4F6F8}.bag-content{padding-top:38rpx}.bag-heading{display:flex;align-items:baseline;justify-content:space-between;margin:0 4rpx 28rpx}.bag-heading text{font-size:48rpx;font-weight:720}.bag-heading .ui-small,.spec,.empty .ui-small{color:#636366;font-size:25rpx}.bag-list{display:flex;flex-direction:column;gap:18rpx}.bag-card{position:relative;display:flex;min-height:210rpx;padding:22rpx;border-radius:26rpx;background:#fff;box-shadow:0 10rpx 28rpx rgba(29,29,31,.055)}.bag-card>image{width:166rpx;height:166rpx;flex:none;border-radius:18rpx;background:#E9EDF2}.bag-info{min-width:0;flex:1;margin-left:22rpx;padding-right:6rpx;display:flex;flex-direction:column}.bag-name{font-size:28rpx;line-height:1.35;font-weight:650}.spec,.protect{margin-top:8rpx;font-size:23rpx}.protect{color:#0B0D10;font-weight:600}.price{margin-top:12rpx;font-size:29rpx;font-weight:700}.actions{margin-top:auto;display:flex;justify-content:space-between;align-items:center}.stepper{display:flex;align-items:center;overflow:hidden;border-radius:99rpx;background:#F4F6F8}.stepper view{width:48rpx;height:46rpx;line-height:46rpx;text-align:center;font-size:28rpx}.stepper text{min-width:42rpx;text-align:center;font-size:24rpx}.remove{margin-right:14rpx;color:#636366;font-size:23rpx}.checkout{position:absolute;top:22rpx;right:22rpx;padding:12rpx 16rpx;border-radius:99rpx;background:#0B0D10;color:#fff;font-size:23rpx;font-weight:650}.total{margin-top:24rpx;padding:28rpx;display:flex;justify-content:space-between;border-radius:22rpx;background:#F4F7FA;font-size:28rpx;font-weight:650}.empty{min-height:70vh;padding-bottom:80rpx;display:flex;flex-direction:column;align-items:center;justify-content:center}.bag-icon{position:relative;width:148rpx;height:148rpx;margin-bottom:34rpx;border-radius:50%;background:#fff}.bag-icon view{position:absolute;left:40rpx;top:55rpx;width:62rpx;height:56rpx;border:3rpx solid #636366;border-radius:0 0 13rpx 13rpx}.bag-icon text{position:absolute;left:57rpx;top:36rpx;width:32rpx;height:22rpx;border:3rpx solid #636366;border-bottom:0;border-radius:22rpx 22rpx 0 0}.empty-title{font-size:34rpx;font-weight:650}.browse{margin-top:42rpx;padding:21rpx 52rpx;border-radius:99rpx;background:#0B0D10;color:#fff;font-size:28rpx;font-weight:600}
</style>
